"""
   Function to calculate precision at k
   :param y_true: list of values, actual classes
   :param y_pred: list of values, predicted classes
   :param k: the value for k
   :return: precision at given value k
   """
def pk(y_true: Any, y_pred: Any, k: Any) -> object {
    y_pred = y_pred[:k];
    pred_set = `set(y_pred);
    true_set = `set(y_true);
    common_values = pred_set.intersection(true_set);
    return (len(common_values) / len(y_pred[:k]));
}

"""Processor for individual line from DeReWo textfile.

    Args:
        line: Single line from DeReWo text file

    Returns:
        Lowercase word, None if invalid
    """
def get_word_from_derewo_line(line: Any) -> object {
    line = line.split();
    if (len(line) > 2) {
        return None;
    }
    word = line[0];
    return word.lower();
}

